const brief = $input.first().json;
const requiredText = ['content_item_id', 'external_key', 'pillar', 'objective', 'audience', 'angle', 'primary_format', 'premise'];
for (const field of requiredText) {
  if (typeof brief[field] !== 'string' || !brief[field].trim()) throw new Error(`Brief invalido: falta ${field}`);
}
for (const field of ['facts', 'sources', 'warnings', 'derived_formats']) {
  if (!Array.isArray(brief[field])) throw new Error(`Brief invalido: ${field} debe ser una lista`);
}
if (!brief.facts.length || !brief.sources.length) throw new Error('Brief invalido: faltan hechos o fuentes');
const sourceIds = new Set(brief.sources.map((source) => source.id));
if (brief.facts.some((fact) => !sourceIds.has(fact.source_id))) throw new Error('Brief invalido: un hecho referencia una fuente ausente');
return [{ json: brief }];

parameters.text:
=Convierte este paquete factual en una pieza maestra de contenido para ARCANUM. Usa solamente los hechos entregados. Devuelve JSON valido, sin markdown. Escribe espanol correcto, incluidas todas las tildes. Cada campo debe aportar algo distinto: no repitas frases ni reformules la misma idea. Una enumeracion de funciones puede aparecer una sola vez en toda la pieza; si el script las enumera, reparte una idea distinta por tarjeta y no vuelvas a enumerarlas en caption. Nombra el producto como app, aplicacion, panel o instrumento; nunca como paginas, volumen, capitulos ni libro. Evita tautologias, solemnidad artificial y relleno arcaizante. No inventes propositos, efectos, ausencia de automatizacion ni filosofias del usuario. No uses azar como opuesto de prediccion. No uses calificadores como preciso, estructurado, riguroso, profundo, metodico o fundamental salvo que aparezcan literalmente en los hechos. El hook debe plantear una tension concreta. carousel debe contener entre 3 y 6 textos no vacios. El CTA debe tener entre 3 y 10 palabras e invitar a una funcion confirmada. source_ids solo puede contener identificadores presentes en sources. Si asset es null, alt_text debe ser una cadena vacia porque la imagen aun no existe.

PAQUETE FACTUAL:
{{ JSON.stringify($json) }}

FORMATO DE SALIDA:
{"hook":"","script":"","carousel":[],"caption":"","cta":"","alt_text":"","source_ids":[],"compliance":{"claims_supported":true,"warnings_applied":true}}

